log.info "=== Debug Information ==="
log.info "Request: ${messageExchange.requestContent}"
log.info "Response: ${messageExchange.responseContent}"
log.info "Status: ${messageExchange.responseHeaders['#status#'][0]}"
log.info "Time: ${messageExchange.timeTaken}ms"

// Dump all context properties
