**Complete E-commerce Mock Service:**

```xml
<mockService name="E-commerce API Mock" port="8080" path="/api/v1">
  <!-- State management script -->
  <script>
    <![CDATA[
      // Initialize storage
      def storage = context.getProperty('ecommerce_storage')
      if (!storage) {
        storage = [
          products: [
            [id: 1, name: "Laptop", price: 999.99, stock: 50, category: "electronics"],
            [id: 2, name: "Mouse", price: 29.99, stock: 200, category: "accessories"],
            [id: 3, name: "Keyboard", price: 79.99, stock: 150, category: "accessories"],
            [id: 4, name: "Monitor", price: 299.99, stock: 30, category: "electronics"],
            [id: 5, name: "Headphones", price: 89.99, stock: 75, category: "audio"]
          ],
          users: [:],
          carts: [:],
          orders: [:],
          counters: [
            userId: 1000,
            orderId: 5000,
            cartId: 2000
          ]
        ]
        context.setProperty('ecommerce_storage', storage)
      }

      // Helper functions
      def findProduct(id) {
        return storage.products.find { it.id == id }
      }

      def updateStock(productId, quantity) {
        def product = findProduct(productId)
        if (product) {
          product.stock -= quantity
          return true
        }
        return false
      }
    ]]>
  </script>

  <!-- Products Endpoints -->
  <mockOperation name="GET /products" method="GET" path="/products">
    <mockResponse name="List Products">
      <script>
        <![CDATA[
          def category = mockRequest.parameters['category']
          def minPrice = mockRequest.parameters['minPrice'] ?: 0
          def maxPrice = mockRequest.parameters['maxPrice'] ?: Double.MAX_VALUE

          def filteredProducts = storage.products.findAll { product ->
            (category ? product.category == category : true) &&
            product.price >= minPrice &&
            product.price <= maxPrice
          }

          mockResponse.setContent(new groovy.json.JsonBuilder([
            data: filteredProducts,
            total: filteredProducts.size()
          ]).toPrettyString())
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <mockOperation name="GET /products/{id}" method="GET" path="/products/{id}">
    <mockResponse name="Get Product">
      <script>
        <![CDATA[
          def id = mockRequest.path.split('/').last().toInteger()
          def product = findProduct(id)

          if (product) {
            mockResponse.setContent(new groovy.json.JsonBuilder(product).toPrettyString())
          } else {
            mockResponse.setHttpResponseCode(404)
            mockResponse.setContent('{"error":"Product not found"}')
          }
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <!-- Cart Endpoints -->
  <mockOperation name="POST /cart" method="POST" path="/cart">
    <mockResponse name="Add to Cart">
      <script>
        <![CDATA[
          def request = new groovy.json.JsonSlurper().parseText(mockRequest.request)
          def cartId = storage.counters.cartId++
          def cart = [
            id: cartId,
            items: request.items,
            createdAt: new Date().toInstant(),
            expiresAt: new Date().toInstant() + 86400000 // 24 hours
          ]
          storage.carts[cartId] = cart

          mockResponse.setHttpResponseCode(201)
          mockResponse.setHeader('Location', "/api/v1/cart/${cartId}")
          mockResponse.setContent(new groovy.json.JsonBuilder([
            cartId: cartId,
            itemCount: request.items.size(),
            total: calculateTotal(request.items)
          ]).toPrettyString())
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <mockOperation name="GET /cart/{id}" method="GET" path="/cart/{id}">
    <mockResponse name="Get Cart">
      <script>
        <![CDATA[
          def id = mockRequest.path.split('/').last().toInteger()
          def cart = storage.carts[id]

          if (cart) {
            // Check expiration
            def now = new Date().toInstant()
            if (now > cart.expiresAt) {
              mockResponse.setHttpResponseCode(410)
              mockResponse.setContent('{"error":"Cart expired"}')
            } else {
              mockResponse.setContent(new groovy.json.JsonBuilder([
                id: cart.id,
                items: cart.items,
                total: calculateTotal(cart.items)
              ]).toPrettyString())
            }
          } else {
            mockResponse.setHttpResponseCode(404)
          }
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <!-- Order Endpoints -->
  <mockOperation name="POST /orders" method="POST" path="/orders">
    <mockResponse name="Create Order">
      <script>
        <![CDATA[
          def request = new groovy.json.JsonSlurper().parseText(mockRequest.request)
          def cart = storage.carts[request.cartId]

          if (!cart) {
            mockResponse.setHttpResponseCode(404)
            mockResponse.setContent('{"error":"Cart not found"}')
            return
          }

          // Validate stock
          def errors = []
          cart.items.each { item ->
            def product = findProduct(item.productId)
            if (!product) {
              errors.add("Product ${item.productId} not found")
            } else if (product.stock < item.quantity) {
              errors.add("Insufficient stock for ${product.name}")
            }
          }

          if (errors) {
            mockResponse.setHttpResponseCode(400)
            mockResponse.setContent(new groovy.json.JsonBuilder([
              error: "Order validation failed",
              details: errors
            ]).toPrettyString())
            return
          }

          // Create order
          def orderId = storage.counters.orderId++
          def order = [
            id: orderId,
            cartId: request.cartId,
            items: cart.items,
            total: calculateTotal(cart.items),
            status: 'confirmed',
            createdAt: new Date().toInstant(),
            paymentStatus: 'pending'
          ]
          storage.orders[orderId] = order

          // Update stock
          cart.items.each { item ->
            updateStock(item.productId, item.quantity)
          }

          // Remove cart
          storage.carts.remove(request.cartId)

          mockResponse.setHttpResponseCode(201)
          mockResponse.setHeader('Location', "/api/v1/orders/${orderId}")
          mockResponse.setContent(new groovy.json.JsonBuilder([
            orderId: orderId,
            status: 'confirmed',
            total: order.total
          ]).toPrettyString())
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <mockOperation name="GET /orders/{id}" method="GET" path="/orders/{id}">
    <mockResponse name="Get Order">
      <script>
        <![CDATA[
          def id = mockRequest.path.split('/').last().toInteger()
          def order = storage.orders[id]

          if (order) {
            mockResponse.setContent(new groovy.json.JsonBuilder(order).toPrettyString())
          } else {
            mockResponse.setHttpResponseCode(404)
          }
        ]]>
      </script>
    </mockResponse>
  </mockOperation>

  <!-- Helper function for calculating totals -->
  <script>
    <![CDATA[
      def calculateTotal(items) {
        def total = 0
        items.each { item ->
          def product = findProduct(item.productId)
          if (product) {
            total += product.price * item.quantity
          }
        }
        return total
      }
    ]]>
  </script>
</mockService>
```

**Testing the Mock:**

```groovy
