    def json = new JsonSlurper().parseText(response)

    // Validate structure
    assert json != null : "Empty response"
    assert json.data != null : "Missing data field"

    // Validate array if present
    if (json.data instanceof List) {
        assert json.data.size() > 0 : "Empty data array"

        // Validate each element
        json.data.eachWithIndex { item, index ->
            assert item.id != null : "Item ${index} missing ID"
            assert item.name != null : "Item ${index} missing name"
        }

        // Check for duplicates
        def ids = json.data.collect { it.id }
        assert ids.unique().size() == ids.size() : "Duplicate IDs found"
    }

    // Validate business rules
    if (json.status == 'success') {
        assert json.error == null : "Success response should not have error"
    } else if (json.status == 'error') {
        assert json.error != null : "Error response missing error message"
    }
}

