// Process CSV
def processCSV(path) {
    def lines = readFile(path).readLines()
    def headers = lines[0].split(',')
    def data = []

    lines[1..-1].each { line ->
        def values = line.split(',')
        def row = [:]
        headers.eachWithIndex { header, index ->
            row[header] = values[index]
        }
        data << row
    }

    return data
}

