**7. Parallel Processing with Groovy:**

```groovy
import java.util.concurrent.*

def executeInParallel(tasks, maxThreads = 5) {
    def executor = Executors.newFixedThreadPool(maxThreads)
    def futures = []

    tasks.each { task ->
        futures << executor.submit({
            try {
                return task()
            } catch (Exception e) {
                log.error "Task failed: ${e.message}"
                return [error: e.message]
            }
        } as Callable)
    }

    def results = futures.collect { it.get() }
    executor.shutdown()

    return results
}

// Example: Test multiple endpoints in parallel
def endpoints = [
    '/users',
    '/products',
    '/orders',
    '/auth/health'
]

def tasks = endpoints.collect { endpoint ->
    return {
        def request = testRunner.testCase.getTestStepByName("Generic GET")
        request.setPropertyValue('endpoint', endpoint)
        request.run(testRunner, context)
        return [
            endpoint: endpoint,
            status: request.getPropertyValue("httpResponseCode"),
            time: request.getPropertyValue("timeTaken")
        ]
    }
}

def results = executeInParallel(tasks, 4)
results.each { result ->
    log.info "${result.endpoint}: ${result.status} (${result.time}ms)"
