```java
// BaseTest.java - Common setup
public abstract class BaseTest {
    protected AppiumDriver driver;

    @BeforeMethod
    public void setUp(@Optional("Android") String platform) {
        DesiredCapabilities caps = new DesiredCapabilities();
        caps.setCapability("platformName", platform);

        if (platform.equals("Android")) {
            caps.setCapability("appium:deviceName", "Pixel 5");
            caps.setCapability("appium:platformVersion", "12.0");
            caps.setCapability("appium:app", System.getProperty("user.dir") + "/apps/app.apk");
            caps.setCapability("appium:automationName", "UiAutomator2");
        } else {
            caps.setCapability("appium:deviceName", "iPhone 13");
            caps.setCapability("appium:platformVersion", "15.0");
            caps.setCapability("appium:app", System.getProperty("user.dir") + "/apps/app.app");
            caps.setCapability("appium:automationName", "XCUITest");
        }

        caps.setCapability("appium:noReset", false);
        caps.setCapability("appium:fullReset", true);

        try {
            driver = new AppiumDriver(new URL("http://localhost:4723"), caps);
            driver.manage().timeouts().implicitlyWait(10, TimeUnit.SECONDS);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create driver: " + e.getMessage());
        }
    }

    @AfterMethod
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }

    protected void takeScreenshot(String testName) {
        File screenshot = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
        try {
            FileUtils.copyFile(screenshot, 
                new File("screenshots/" + testName + "_" + System.currentTimeMillis() + ".png"));
        } catch (IOException e) {
            System.err.println("Failed to save screenshot: " + e.getMessage());
        }
    }
}

// LoginPage.java
public class LoginPage {
    private AppiumDriver driver;
    private WebDriverWait wait;

    // Locators
    @AndroidFindBy(id = "com.example.app:id/username")
    @iOSXCUITFindBy(accessibility = "username")
    private WebElement usernameField;

    @AndroidFindBy(id = "com.example.app:id/password")
    @iOSXCUITFindBy(accessibility = "password")
    private WebElement passwordField;

    @AndroidFindBy(id = "com.example.app:id/loginButton")
    @iOSXCUITFindBy(accessibility = "loginButton")
    private WebElement loginButton;

    @AndroidFindBy(id = "com.example.app:id/welcomeMessage")
    @iOSXCUITFindBy(accessibility = "welcomeMessage")
    private WebElement welcomeMessage;

    @AndroidFindBy(id = "com.example.app:id/errorMessage")
    @iOSXCUITFindBy(accessibility = "errorMessage")
    private WebElement errorMessage;

    public LoginPage(AppiumDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, 10);
        PageFactory.initElements(new AppiumFieldDecorator(driver), this);
    }

    public void login(String username, String password) {
        try {
            wait.until(ExpectedConditions.visibilityOf(usernameField));
            usernameField.clear();
            usernameField.sendKeys(username);

            passwordField.clear();
            passwordField.sendKeys(password);

            loginButton.click();
        } catch (Exception e) {
            throw new RuntimeException("Login failed: " + e.getMessage());
        }
    }

    public String getWelcomeMessage() {
        wait.until(ExpectedConditions.visibilityOf(welcomeMessage));
        return welcomeMessage.getText();
    }

    public String getErrorMessage() {
        wait.until(ExpectedConditions.visibilityOf(errorMessage));
        return errorMessage.getText();
    }

    public boolean isWelcomeMessageDisplayed() {
        try {
            return welcomeMessage.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }
}

// LoginTest.java
public class LoginTest extends BaseTest {
    private LoginPage loginPage;

    @BeforeMethod
    public void initPages() {
        loginPage = new LoginPage(driver);
    }

    @Test(description = "Verify successful login with valid credentials")
    public void testValidLogin() {
        // Arrange
        String username = "testuser";
        String password = "pass123";

        // Act
        loginPage.login(username, password);

        // Assert
        Assert.assertTrue(loginPage.isWelcomeMessageDisplayed(), 
            "Welcome message not displayed");
        Assert.assertEquals(loginPage.getWelcomeMessage(), 
            "Welcome, testuser!", 
            "Welcome message text incorrect");
    }

    @Test(description = "Verify login fails with invalid password")
    public void testInvalidPassword() {
        // Arrange
        String username = "testuser";
        String password = "wrongpass";

        // Act
        loginPage.login(username, password);

        // Assert
        String error = loginPage.getErrorMessage();
        Assert.assertTrue(error.contains("Invalid"), 
            "Error message should indicate invalid credentials");
    }

    @Test(description = "Verify login fails with empty username")
    public void testEmptyUsername() {
        // Arrange
        String username = "";
        String password = "pass123";

        // Act
        loginPage.login(username, password);

        // Assert
        String error = loginPage.getErrorMessage();
        Assert.assertTrue(error.contains("required"), 
            "Error message should indicate required field");
    }

    @DataProvider(name = "invalidCredentials")
    public Object[][] invalidCredentials() {
        return new Object[][] {
            {"", "pass123", "username required"},
            {"testuser", "", "password required"},
            {"", "", "fields required"},
            {"invalid", "wrong", "Invalid credentials"}
        };
    }

    @Test(dataProvider = "invalidCredentials", description = "Verify various invalid scenarios")
    public void testInvalidScenarios(String username, String password, String expectedError) {
        // Act
        loginPage.login(username, password);

        // Assert
        String error = loginPage.getErrorMessage().toLowerCase();
        Assert.assertTrue(error.contains(expectedError.toLowerCase()), 
            String.format("Expected '%s' in error message, got '%s'", expectedError, error));
    }

    @AfterMethod(alwaysRun = true)
    public void takeScreenshotOnFailure(ITestResult result) {
        if (result.getStatus() == ITestResult.FAILURE) {
            takeScreenshot(result.getName());
        }
    }
}
