// config/AppiumConfig.java
public class AppiumConfig {
    private static final Properties props = new Properties();

    static {
        String env = System.getProperty("test.env", "dev");
        try (InputStream input = AppiumConfig.class.getClassLoader()
                .getResourceAsStream("appium-" + env + ".properties")) {
            props.load(input);
        } catch (IOException e) {
            throw new RuntimeException("Failed to load config", e);
        }
    }

    public static String getAppPath() {
        return props.getProperty("app.path");
    }

    public static String getDeviceName() {
        return props.getProperty("device.name");
    }

    public static String getPlatformVersion() {
        return props.getProperty("platform.version");
    }

    public static DesiredCapabilities getCapabilities() {
