```java
public class BrowserCompat {

    public static By getSelector(String element, String browser) {
        Map<String, Map<String, String>> selectors = new HashMap<>();

        // Login button selectors per browser
        Map<String, String> loginSelectors = new HashMap<>();
        loginSelectors.put("Chrome", "button.login");
        loginSelectors.put("Safari", ".login-button");
        loginSelectors.put("Firefox", "#login-btn");
        selectors.put("login", loginSelectors);

        return By.cssSelector(selectors.get(element).get(browser));
    }

    public static void executeWithRetry(WebDriver driver, Runnable action, 
                                        String browser) {
        int retries = browser.equals("Safari") ? 3 : 1;
        for (int i = 0; i < retries; i++) {
            try {
                action.run();
                break;
            } catch (Exception e) {
                if (i == retries - 1) throw e;
                try { Thread.sleep(1000); } catch (InterruptedException ignored) {}
            }
        }
    }
}

// Usage
BrowserCompat.executeWithRetry(driver, () -> {
    driver.findElement(BrowserCompat.getSelector("login", browser)).click();
}, browser);
