public class EcommerceMobileWebTest extends BaseWebTest {

    private HomePage homePage;
    private ProductPage productPage;
    private CartPage cartPage;
    private CheckoutPage checkoutPage;

    @BeforeMethod
    public void initPages() {
        homePage = new HomePage(driver);
        productPage = new ProductPage(driver);
        cartPage = new CartPage(driver);
        checkoutPage = new CheckoutPage(driver);
    }

    @Test(description = "Homepage loads correctly on mobile")
    public void testHomepageResponsive() {
        driver.get(baseUrl);

        // Verify mobile menu is visible
        assertTrue(homePage.isMobileMenuVisible(), 
            "Mobile menu should be visible");

        // Verify search bar is present
        assertTrue(homePage.isSearchBarPresent(), 
            "Search bar should be present");

        // Verify product grid is 2 columns (mobile layout)
        assertEquals(homePage.getProductGridColumns(), 2, 
            "Product grid should show 2 columns on mobile");

        // Scroll down and verify infinite scroll works
        homePage.scrollToBottom();
        assertTrue(homePage.getProductCount() > 20, 
            "Should load more products on scroll");
    }

    @Test(description = "Product search works on mobile")
    public void testProductSearch() {
        driver.get(baseUrl);

        homePage.searchFor("smartphone");

        // Verify search results
        assertTrue(productPage.getProductCount() > 0, 
            "Should show search results");

        // Apply filter (mobile-specific UI)
        productPage.openFilters();
        productPage.applyFilter("Price", "Under $500");

        // Verify filtered results
        List<Double> prices = productPage.getAllPrices();
        for (Double price : prices) {
            assertTrue(price < 500, 
                "All products should be under $500");
        }
    }

    @Test(description = "Product details page on mobile")
    public void testProductDetails() {
        driver.get(baseUrl + "/product/123");

        // Verify image gallery with swipe
        String firstImage = productPage.getCurrentImage();
        productPage.swipeLeftOnImage();
        String secondImage = productPage.getCurrentImage();
        assertNotEquals(firstImage, secondImage, 
            "Image should change on swipe");

        // Verify add to cart
        productPage.selectSize("M");
        productPage.selectColor("Black");
        productPage.addToCart();

        // Verify cart update
        assertEquals(productPage.getCartCount(), 1, 
            "Cart should have 1 item");

        // Test zoom on image
        productPage.pinchToZoom();
        assertTrue(productPage.isImageZoomed(), 
            "Image should zoom on pinch");
    }

    @Test(description = "Shopping cart on mobile")
    public void testShoppingCart() {
        // Add items to cart
        driver.get(baseUrl + "/product/123");
        productPage.addToCart();

        driver.get(baseUrl + "/product/456");
        productPage.addToCart();

        // Go to cart
        cartPage.open();

        // Verify items
        assertEquals(cartPage.getItemCount(), 2, 
            "Cart should have 2 items");

        // Update quantity
        cartPage.updateQuantity(0, 2);

        // Verify total updated
        double subtotal = cartPage.getSubtotal();
        double shipping = cartPage.getShipping();
        double total = cartPage.getTotal();
        assertEquals(total, subtotal + shipping, 0.01, 
            "Total should be subtotal + shipping");

        // Remove item
        cartPage.removeItem(1);
        assertEquals(cartPage.getItemCount(), 1, 
            "Cart should have 1 item after removal");
    }

    @Test(description = "Mobile checkout flow")
    public void testCheckoutFlow() {
        // Add item and go to checkout
        driver.get(baseUrl + "/product/123");
        productPage.addToCart();
        productPage.goToCheckout();

        // Guest checkout (mobile optimized form)
        checkoutPage.checkoutAsGuest();

        // Fill shipping info (mobile keyboard)
        checkoutPage.enterShippingInfo(
            "John Doe",
            "123 Main St",
            "New York",
            "NY",
            "10001",
            "555-1234"
        );

        // Continue to payment
        checkoutPage.clickContinue();

        // Enter payment (mobile-friendly form)
        checkoutPage.enterPaymentInfo(
            "4111111111111111",
            "12/25",
            "123"
        );

        // Place order
        checkoutPage.placeOrder();

        // Verify order confirmation
        assertTrue(checkoutPage.isOrderConfirmed(), 
            "Order should be confirmed");
        String orderNumber = checkoutPage.getOrderNumber();
        assertNotNull(orderNumber, "Should get order number");
    }

    @Test(description = "Test on different network conditions")
    @Parameters({"networkSpeed"})
    public void testNetworkConditions(String networkSpeed) {
        // Set network condition
        Map<String, Object> params = new HashMap<>();
        params.put("networkSpeed", networkSpeed);
        driver.executeScript("mobile: setNetworkSpeed", params);

        long start = System.currentTimeMillis();
        driver.get(baseUrl);
        long loadTime = System.currentTimeMillis() - start;

        System.out.println("Load time on " + networkSpeed + ": " + loadTime + "ms");

        // Assert based on network speed
        switch(networkSpeed) {
            case "WiFi":
                assertTrue(loadTime < 2000, 
                    "WiFi load time under 2 seconds");
                break;
            case "4G":
                assertTrue(loadTime < 4000, 
                    "4G load time under 4 seconds");
                break;
            case "3G":
                assertTrue(loadTime < 10000, 
                    "3G load time under 10 seconds");
                break;
        }
    }

    @Test(description = "Test orientation changes")
    public void testOrientationChanges() {
        driver.get(baseUrl);

        // Initial orientation
        String initialLayout = homePage.getLayoutType();

        // Rotate to landscape
        driver.rotate(ScreenOrientation.LANDSCAPE);
        Thread.sleep(2000); // Wait for reflow

        // Layout should change
        String landscapeLayout = homePage.getLayoutType();
        assertNotEquals(initialLayout, landscapeLayout, 
            "Layout should change on rotation");

        // Verify no broken elements
        assertTrue(homePage.verifyNoOverlappingElements(), 
            "No elements should overlap in landscape");

        // Rotate back
        driver.rotate(ScreenOrientation.PORTRAIT);
        Thread.sleep(2000);

        assertEquals(homePage.getLayoutType(), initialLayout, 
            "Should return to original layout");
    }

    @AfterMethod
    public void logTestResult(ITestResult result) {
        if (result.getStatus() == ITestResult.FAILURE) {
            takeScreenshot(result.getName());

            // Capture browser logs
            LogEntries logs = driver.manage().logs().get("browser");
            for (LogEntry entry : logs) {
                if (entry.getLevel().equals(Level.SEVERE)) {
                    System.err.println("Browser error: " + entry.getMessage());
                }
            }
        }
    }
}
